/**
 * The whole trainer catalogue (Pokémon Showdown, 80×80 PNGs in `public/sprites/trainers/`): every allowed slug,
 * its readable name, its group and its author, plus the search and filters the profile picker uses.
 * Shared by the client (picker) and the server (the only slugs PATCH /api/auth/me accepts). The data is
 * `trainerCatalog.json`, generated by `npm run download:trainers -- --update`.
 *
 * Groups (each sprite is in exactly one):
 * - `featured`: the 24 hand-picked ones (`TRAINER_CORE`), the default pool.
 * - `classic`: the other stock Showdown sprites, with no credit.
 * - `older`: stock sprites drawn for an older game (`-gen1` … `-gen5`), filterable by generation.
 * - `fan`: fan art with an author, filterable by author.
 */
import catalog from './trainerCatalog.json'
import { defaultTrainerSprite, TRAINER_CORE } from './trainers'

export type TrainerGroup = 'featured' | 'classic' | 'older' | 'fan'
export const TRAINER_GROUPS: readonly TrainerGroup[] = ['featured', 'classic', 'older', 'fan']

export interface TrainerEntry {
  slug: string
  /** English name made from the slug («Ace Trainer», «Gen 3 RS» variants). Core sprites have translated names in the locales. */
  label: string
  group: TrainerGroup
  /** `gen3` for `older`, the author for `fan`, '' otherwise. */
  sub: string
  /** Author of a fan sprite, '' for stock ones. */
  credit: string
  /** Normalised haystack for the search (label, slug, author). */
  search: string
}

// ---------------------------------------------------------------------------
// Names
// ---------------------------------------------------------------------------

/** Slug words that are several words glued together (or have punctuation). The rest are just capitalised. */
const WORDS: Record<string, string> = {
  acetrainer: 'Ace Trainer',
  acetrainercouple: 'Ace Trainer Couple',
  acetrainersnow: 'Ace Trainer Snow',
  aromalady: 'Aroma Lady',
  battlegirl: 'Battle Girl',
  birdkeeper: 'Bird Keeper',
  blackbelt: 'Black Belt',
  bugcatcher: 'Bug Catcher',
  bugmaniac: 'Bug Maniac',
  capbackward: 'Cap Backward',
  crasherwake: 'Crasher Wake',
  crushgirl: 'Crush Girl',
  crushkin: 'Crush Kin',
  cueball: 'Cue Ball',
  depotagent: 'Depot Agent',
  doubleteam: 'Double Team',
  dragontamer: 'Dragon Tamer',
  firebreather: 'Fire Breather',
  galacticgrunt: 'Galactic Grunt',
  hexmaniac: 'Hex Maniac',
  jessiejames: 'Jessie & James',
  jrtrainer: 'Jr. Trainer',
  kimonogirl: 'Kimono Girl',
  ltsurge: 'Lt. Surge',
  mrfuji: 'Mr. Fuji',
  ninjaboy: 'Ninja Boy',
  nurseryaide: 'Nursery Aide',
  oldcouple: 'Old Couple',
  parasollady: 'Parasol Lady',
  plasmagrunt: 'Plasma Grunt',
  pokeathlon: 'Pokéathlon',
  pokefan: 'Poké Fan',
  pokekid: 'Poké Kid',
  pokemaniac: 'Poké Maniac',
  pokemonbreeder: 'Pokémon Breeder',
  pokemonranger: 'Pokémon Ranger',
  rocketexecutive: 'Rocket Executive',
  rocketgrunt: 'Rocket Grunt',
  ruinmaniac: 'Ruin Maniac',
  schoolkid: 'School Kid',
  shadowtriad: 'Shadow Triad',
  sisandbro: 'Sis & Bro',
  srandjr: 'Sr. & Jr.',
  supernerd: 'Super Nerd',
  tateandliza: 'Tate & Liza',
  teamaquabeta: 'Team Aqua (beta)',
  teamaquagrunt: 'Team Aqua Grunt',
  teammagmagrunt: 'Team Magma Grunt',
  teamrocket: 'Team Rocket',
  teamrocketgrunt: 'Team Rocket Grunt',
  triathletebiker: 'Triathlete Biker',
  triathleterunner: 'Triathlete Runner',
  triathleteswimmer: 'Triathlete Swimmer',
  wonderlauncher: 'Wonder Launcher',
  workerice: 'Worker (Ice)',
  youngcouple: 'Young Couple',
}

const GEN_RE = /^(.+?)-gen(\d)(.*)$/
const cap = (w: string) => (w ? w[0]!.toUpperCase() + w.slice(1) : w)

const GEN_WORDS = /(champion|main|title|two|kanto)/

/** `3` + `rs` → «Gen 3 RS»; `1` + `rbtwo` → «Gen 1 RB Two»: real words are capitalised, game codes upper-cased. */
function genText(n: string, rest: string): string {
  const parts = rest.replace(GEN_WORDS, ' $1 ').split(' ').filter(Boolean).map((p) => (GEN_WORDS.test(p) ? cap(p) : p.toUpperCase()))
  return ['Gen', n, ...parts].join(' ')
}

/** The word of a slug part: «bugcatcher» → «Bug Catcher», «masters2» → «Masters 2». */
function word(w: string, stems: ReadonlySet<string>): string {
  const known = WORDS[w]
  if (known) return known
  // «acetrainerf» / «swimmerm»: the same character in the other gender, only when the plain one exists.
  const g = w.slice(-1)
  const stem = w.slice(0, -1)
  if ((g === 'f' || g === 'm') && (WORDS[stem] || stems.has(stem))) return `${word(stem, stems)} (${g.toUpperCase()})`
  return cap(w).replace(/([a-z])(\d+)$/, '$1 $2')
}

/** Readable English name of a slug. `stems` = every part of every slug (to tell «lassf» from a name ending in f). */
export function trainerLabel(slug: string, stems: ReadonlySet<string>): string {
  const gen = GEN_RE.exec(slug)
  const base = gen ? gen[1]! : slug
  const text = base.split('-').map((w) => word(w, stems)).join(' ')
  return gen ? `${text} (${genText(gen[2]!, gen[3]!)})` : text
}

/** Lower case, no accents, letters and digits only: «Poké Fan», «pokefan» and «poke-fan» all give `pokefan`. */
export function normalizeSearch(s: string): string {
  return s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '')
}

// ---------------------------------------------------------------------------
// The catalogue
// ---------------------------------------------------------------------------

const data = catalog as { classic: string[]; fan: Record<string, string[]> }
const core = new Set(TRAINER_CORE)

const stems: ReadonlySet<string> = new Set([...data.classic, ...Object.values(data.fan).flat()].flatMap((s) => s.replace(/-gen\d.*$/, '').split('-')))

function entry(slug: string, group: TrainerGroup, sub: string, credit: string): TrainerEntry {
  const label = trainerLabel(slug, stems)
  return { slug, label, group, sub, credit, search: normalizeSearch(`${label} ${slug} ${credit}`) }
}

function build(): TrainerEntry[] {
  const out: TrainerEntry[] = []
  const bySlug = new Map<string, TrainerEntry>()
  for (const slug of TRAINER_CORE) {
    const e = entry(slug, 'featured', '', '')
    out.push(e)
    bySlug.set(slug, e)
  }
  const stock = data.classic.filter((s) => !core.has(s))
  for (const slug of stock.filter((s) => !GEN_RE.test(s))) out.push(entry(slug, 'classic', '', ''))
  const older = stock
    .filter((s) => GEN_RE.test(s))
    .map((s) => ({ s, n: Number(GEN_RE.exec(s)![2]) }))
    .sort((a, b) => a.n - b.n || (a.s < b.s ? -1 : 1))
  for (const { s, n } of older) out.push(entry(s, 'older', `gen${n}`, ''))
  for (const [author, slugs] of Object.entries(data.fan)) for (const slug of slugs) out.push(entry(slug, 'fan', author, author))
  return out
}

/** Every character, in picker order: featured, classic, older (by generation), fan (by author). */
export const TRAINER_CATALOG: readonly TrainerEntry[] = build()

const BY_SLUG: ReadonlyMap<string, TrainerEntry> = new Map(TRAINER_CATALOG.map((e) => [e.slug, e]))

export function trainerEntry(slug: string): TrainerEntry | undefined {
  return BY_SLUG.get(slug)
}

export function isTrainerSprite(slug: unknown): slug is string {
  return typeof slug === 'string' && BY_SLUG.has(slug)
}

/** The saved choice if it is still in the catalogue, else the default of the account. */
export function resolveTrainerSprite(userId: string, stored: string | null | undefined): string {
  return isTrainerSprite(stored) ? stored : defaultTrainerSprite(userId)
}

/** Generations with variants (`gen1` …), in order. */
export const TRAINER_GENS: readonly string[] = [...new Set(TRAINER_CATALOG.filter((e) => e.group === 'older').map((e) => e.sub))]

/** Fan-art authors with their sprite count, biggest first. */
export const TRAINER_AUTHORS: readonly { author: string; count: number }[] = Object.entries(data.fan).map(([author, slugs]) => ({ author, count: slugs.length }))

// ---------------------------------------------------------------------------
// Search and filters
// ---------------------------------------------------------------------------

export interface TrainerFilter {
  /** `all` = every group. */
  group: TrainerGroup | 'all'
  /** A generation (`gen3`) inside `older`, an author inside `fan`; '' = all of the group. */
  sub?: string
  /** Free text: every word must match the name, slug or author (accents, case and spaces do not matter). */
  query?: string
  /** The name the player sees for a sprite when it is not `label` (the translated names of the featured ones). */
  localName?: (slug: string) => string | undefined
}

function matcher(query: string | undefined, localName?: TrainerFilter['localName']): (e: TrainerEntry) => boolean {
  const words = (query ?? '').split(/[\s-]+/).map(normalizeSearch).filter(Boolean)
  if (words.length === 0) return () => true
  return (e) => {
    const hay = localName ? e.search + normalizeSearch(localName(e.slug) ?? '') : e.search
    return words.every((w) => hay.includes(w))
  }
}

export function filterTrainers(f: TrainerFilter): TrainerEntry[] {
  const match = matcher(f.query, f.localName)
  return TRAINER_CATALOG.filter((e) => (f.group === 'all' || e.group === f.group) && (!f.sub || e.sub === f.sub) && match(e))
}

/** How many sprites match the text in each group (the chips show it, so a search tells you where the results are). */
export function countByGroup(query: string | undefined, localName?: TrainerFilter['localName']): Record<TrainerGroup | 'all', number> {
  const match = matcher(query, localName)
  const out: Record<TrainerGroup | 'all', number> = { all: 0, featured: 0, classic: 0, older: 0, fan: 0 }
  for (const e of TRAINER_CATALOG) {
    if (!match(e)) continue
    out.all++
    out[e.group]++
  }
  return out
}

/** Matches of the text per generation / author inside a group (for the sub-filter). */
export function countBySub(group: 'older' | 'fan', query: string | undefined, localName?: TrainerFilter['localName']): Map<string, number> {
  const match = matcher(query, localName)
  const out = new Map<string, number>()
  for (const e of TRAINER_CATALOG) if (e.group === group && match(e)) out.set(e.sub, (out.get(e.sub) ?? 0) + 1)
  return out
}

/** A random sprite of the list other than `not` (null when there is none). */
export function randomTrainer(list: readonly TrainerEntry[], not?: string, rng: () => number = Math.random): TrainerEntry | null {
  const pool = list.filter((e) => e.slug !== not)
  return pool.length ? pool[Math.floor(rng() * pool.length)]! : null
}
